import { useState } from "react";
import dynamic from "next/dynamic";
import clsx from "clsx";
import { usePage } from "../contexts.jsx";
import { Badge, Button, Chevron, Picture, Timestamp } from "../ui/primitives.jsx";
import { Icon } from "../ui/icons.jsx";
import { Teaser } from "../teasers/layouts.jsx";
import { CommercialSlot, CompanionGroup, RecommendationContainer } from "../stages/parts.jsx";
import { formatDate, formatTime } from "../../lib/format.js";
import { interactionTracking } from "../../lib/tracking.js";
import { trackImport } from "../../lib/track-import.js";
import { Anchor, Box, Item, Paragraph, Text } from "../ui/ds.jsx";

const Quote = dynamic(() => import("./blocks.jsx").then((m) => m.Quote));
const FactBox = dynamic(() => import("./blocks.jsx").then((m) => m.FactBox));
const ReadAlso = dynamic(() => import("./blocks.jsx").then((m) => m.ReadAlso));
const ReadingProgress = dynamic(() => trackImport(import("./ReadingProgress.jsx")), { ssr: false });
const ShareMenu = dynamic(() => trackImport(import("./ShareMenu.jsx")), { ssr: false });

function Breadcrumb({ items }) {
    return (
        <nav aria-label="Brotkrumen" className="mb-4">
            <ol className="flex flex-wrap items-center gap-1 text-xs text-ink-500">
                {items.map((item, i) => (
                    <Item key={item.href} className="flex items-center gap-1">
                        {i > 0 ? <Icon name="chevronRight" size={12} /> : null}
                        <Anchor href={item.href} className="hover:text-brand-600 hover:underline">{item.label}</Anchor>
                    </Item>
                ))}
            </ol>
        </nav>
    );
}

function Authors({ article }) {
    return (
        <Box className="flex flex-wrap items-center gap-3 border-y border-ink-200 py-3 text-sm dark:border-ink-700">
            {article.authors.map((author, i) => (
                <Text key={i} className="flex items-center gap-2">
                    <Text className="grid size-9 place-items-center rounded-full bg-brand-100 font-bold text-brand-700">{author.name[0]}</Text>
                    <Text>
                        <Text className="block font-bold text-ink-900 dark:text-ink-50">{author.degree}{author.name}</Text>
                        <Text className="block text-xs text-ink-500">{author.role}</Text>
                    </Text>
                </Text>
            ))}
            <Text className="ml-auto text-xs text-ink-500">
                {formatDate(article.published)}, {formatTime(article.published)}
                {article.updated ? <> · Aktualisiert {formatTime(article.updated)}</> : null}
                {" · "}Lesedauer: {article.readingTime} Min.
            </Text>
            <ShareMenu />
        </Box>
    );
}

function ArticleHeader({ article }) {
    return (
        <header className="mb-5">
            <Paragraph className="mb-2 flex items-center gap-2 text-base font-medium text-brand-600">
                {article.genreLabel ? <Badge tone="opinion">{article.genreLabel}</Badge> : null}
                {article.topLine}
            </Paragraph>
            <h1 className="font-serif text-head-xl font-semibold text-balance text-ink-900 hyphens-auto dark:text-ink-50">{article.headline}</h1>
        </header>
    );
}

function Figure({ picture, priority }) {
    return (
        <figure className="my-6">
            <Picture picture={picture} priority={priority} sizes="(min-width: 1024px) 660px, 100vw" className="rounded-teaser" />
            <figcaption className="mt-2 text-xs leading-relaxed text-ink-600">
                {picture.captionRichText.map((run, i) => <Text key={i}>{run.text}</Text>)}
                <Text className="ml-1 text-ink-400">({picture.source})</Text>
            </figcaption>
        </figure>
    );
}

function ArticleParagraph({ text }) {
    return <Paragraph className="text-[1.125rem] leading-[1.7] text-ink-800 hyphens-auto dark:text-ink-100">{text}</Paragraph>;
}

function Subheadline({ text }) {
    return <h2 className="mt-8 mb-3 text-head-m font-bold text-ink-900 dark:text-ink-50">{text}</h2>;
}

function Block({ block }) {
    switch (block.type) {
    case "lead":
        return <Paragraph className="mb-6 text-[1.1875rem] leading-relaxed font-bold text-ink-900 dark:text-ink-50">{block.text}</Paragraph>;
    case "paragraph":
        return <ArticleParagraph text={block.text} />;
    case "subheadline":
        return <Subheadline text={block.text} />;
    case "image":
        return <Figure picture={block.picture} />;
    case "quote":
        return <Quote text={block.text} author={block.author} />;
    case "factBox":
        return <FactBox title={block.title} items={block.items} />;
    case "readAlso":
        return <ReadAlso teasers={block.teasers} />;
    case "commercial":
        return <CommercialSlot name={block.slot} sizes="640x360,300x250" lazy minHeight={360} className="my-6 w-full" />;
    default:
        return null;
    }
}

function TrustBox({ trust }) {
    const [open, setOpen] = useState(false);
    return (
        <section className="mt-10 rounded-teaser border border-ink-200 bg-paper-muted p-5 dark:border-ink-700" aria-label="Transparenz">
            <Button aria-expanded={open} aria-label="Woher stammen die Informationen?" onClick={() => setOpen(!open)} className="w-full justify-between text-left text-base font-bold" {...interactionTracking("trust-box")}>
                <Text className="flex items-center gap-2"><Icon name="check" className="text-ok-500" />Woher stammen die Informationen?</Text>
                <Chevron open={open} />
            </Button>
            {open ? (
                <Box className="mt-4 animate-fade-in text-sm leading-relaxed text-ink-700">
                    <Paragraph>{trust.method}</Paragraph>
                    <h3 className="mt-3 mb-1 font-bold">Verwendete Quellen</h3>
                    <ul className="list-disc pl-5">
                        {trust.sources.map((source, i) => <Item key={i}>{source}</Item>)}
                    </ul>
                </Box>
            ) : null}
        </section>
    );
}

function RelatedArticles({ teasers }) {
    const [expanded, setExpanded] = useState(false);
    const shown = expanded ? teasers : teasers.slice(0, 3);
    return (
        <section className="mt-10" aria-label="Mehr zum Thema">
            <h2 className="mb-4 border-t-4 border-brand-600 pt-3 text-head-m font-bold uppercase">Mehr zum Thema</h2>
            <Box className="flex flex-col gap-(--teaser-gap)">
                {shown.map((teaser) => <Teaser key={teaser.id} teaser={teaser} />)}
            </Box>
            <Box className="mt-4 flex justify-center">
                <Button variant="outline" aria-expanded={expanded} aria-label="Weitere Artikel zum Thema" onClick={() => setExpanded(!expanded)} {...interactionTracking("related-more")}>
                    {expanded ? "Weniger anzeigen" : "Weitere Artikel"}
                    <Chevron open={expanded} />
                </Button>
            </Box>
        </section>
    );
}

function TopicTags({ topics }) {
    return (
        <nav aria-label="Themen" className="mt-8">
            <h2 className="mb-2 text-xs font-bold text-ink-500 uppercase">Themen</h2>
            <ul className="flex flex-wrap gap-2">
                {topics.map((topic) => (
                    <Item key={topic.href}>
                        <Anchor href={topic.href} className="inline-block rounded-chip border border-ink-300 px-3 py-1 text-sm text-ink-700 transition-colors hover:border-brand-500 hover:bg-brand-50 hover:text-brand-700 md:text-[0.9375rem]">{topic.label}</Anchor>
                    </Item>
                ))}
            </ul>
        </nav>
    );
}

function AuthorBox({ authors }) {
    if (!authors.length)
        return null;
    return (
        <section aria-label="Autoren" className="mt-8 flex flex-col gap-4 rounded-teaser bg-paper-muted p-5 md:flex-row dark:bg-paper-raised">
            {authors.map((author, i) => (
                <Box key={i} className="flex flex-1 items-start gap-3">
                    <Text className="grid size-14 shrink-0 place-items-center rounded-full bg-brand-600 text-head-s font-bold text-white">{author.name[0]}</Text>
                    <Box>
                        <Paragraph className="font-bold text-ink-900">{author.degree}{author.name}</Paragraph>
                        <Paragraph className="text-sm text-ink-600">{author.role} im Ressort Politik</Paragraph>
                        <Anchor href="autoren/" className="mt-1 inline-block text-sm font-medium text-brand-600 hover:underline">Alle Artikel</Anchor>
                    </Box>
                </Box>
            ))}
        </section>
    );
}

function GalleryStrip({ pictures }) {
    return (
        <section aria-label="Bilderserie" className="my-8">
            <h2 className="mb-3 flex items-center gap-2 text-head-s font-bold"><Icon name="gallery" />Bilderserie</h2>
            <ul className="grid grid-cols-3 gap-2 md:grid-cols-6">
                {pictures.map((picture) => (
                    <Item key={picture.id} className="overflow-hidden rounded-sm">
                        <Picture picture={picture} ratio="3x2" sizes="160px" />
                    </Item>
                ))}
            </ul>
        </section>
    );
}

export function ArticlePage() {
    const page = usePage();
    const { article } = page;
    return (
        <Box className="grid grid-cols-1 gap-8 desk:grid-cols-[minmax(0,1fr)_18.75rem]">
            <ReadingProgress />
            <article className={clsx("min-w-0")} data-article-id={article.id}>
                <Breadcrumb items={page.breadcrumb} />
                <ArticleHeader article={article} />
                <Authors article={article} />
                <Figure picture={article.image} priority />
                <Box className="article-copy">
                    {article.body.map((block, i) => <Block key={i} block={block} />)}
                </Box>
                <Paragraph className="mt-6 text-xs text-ink-500">Stand: <Timestamp value={article.updated ?? article.published} relative={false} /></Paragraph>
                <GalleryStrip pictures={page.gallery} />
                <TopicTags topics={page.topics} />
                <AuthorBox authors={article.authors} />
                <TrustBox trust={article.trust} />
                <RelatedArticles teasers={page.related} />
                <CommercialSlot name="banner2" sizes="800x250,728x90" lazy minHeight={250} className="my-8 w-full" />
                <RecommendationContainer placement="article-below" mode="feed" className="mt-8" />
            </article>
            <aside className="flex flex-col gap-5">
                <CommercialSlot name="rectangle" sizes="300x250" minHeight={250} className="w-[300px]" />
                <CompanionGroup group={page.topNews} />
                <RecommendationContainer placement="article-sidebar" />
                <CompanionGroup group={page.moreFromSection} />
                <CompanionGroup group={page.mostRead} />
                {page.sidebarGroups.map((group) => <CompanionGroup key={group.index} group={group} />)}
            </aside>
        </Box>
    );
}
