import { PageShell } from "../../components/layout/PageShell.jsx";
import { ArticlePage } from "../../components/article/Article.jsx";

export default function Article() {
    return (
        <PageShell>
            <ArticlePage />
        </PageShell>
    );
}

export async function getStaticPaths() {
    return { paths: [{ params: { id: "story" } }], fallback: false };
}

export async function getStaticProps() {
    const { loadPage } = await import("../../lib/page-props.js");
    return { props: { page: loadPage("article") } };
}
